/*
 * Minimal freestanding C library for the MIPS32 JavaScript VM (vm.js).
 *
 * Only the syscalls implemented by vm.js are used:
 *   0 = read, 1 = write, 2 = open, 3 = close, 8 = lseek,
 *   38 = rename, 39 = mkdir, 201 = time
 */

