/* ------------------------------------------------------------------ */
/* raw system calls                                                     */
/* ------------------------------------------------------------------ */

#define SYS_read   0
#define SYS_write  1
#define SYS_open   2
#define SYS_close  3
#define SYS_lseek  8
#define SYS_rename 38
#define SYS_mkdir  39
#define SYS_time   201

static inline int __syscall(int n, int a, int b, int c)
{
    register int v0 asm("$2") = n;
    register int a0 asm("$4") = a;
    register int a1 asm("$5") = b;
    register int a2 asm("$6") = c;

    asm volatile ("syscall"
                  : "+r"(v0), "+r"(a0), "+r"(a1), "+r"(a2)
                  :
                  : "$7", "memory");
    return v0;
}

ssize_t read(int fd, void *buf, size_t n)
{
    return __syscall(SYS_read, fd, (int)buf, (int)n);
}

ssize_t write(int fd, const void *buf, size_t n)
{
    return __syscall(SYS_write, fd, (int)buf, (int)n);
}

int open(const char *path, int flags, ...)
{
    va_list ap;
    int mode = 0666;

    va_start(ap, flags);
    if (flags & O_CREAT)
        mode = va_arg(ap, int);
    va_end(ap);

    return __syscall(SYS_open, (int)path, flags, mode);
}

int creat(const char *path, mode_t mode)
{
    return open(path, O_WRONLY | O_CREAT | O_TRUNC, (int)mode);
}

int close(int fd)
{
    return __syscall(SYS_close, fd, 0, 0);
}

off_t lseek(int fd, off_t off, int whence)
{
    return __syscall(SYS_lseek, fd, (int)off, whence);
}

int rename(const char *from, const char *to)
{
    return __syscall(SYS_rename, (int)from, (int)to, 0);
}

int mkdir(const char *path, mode_t mode)
{
    return __syscall(SYS_mkdir, (int)path, (int)mode, 0);
}

int chmod(const char *path, mode_t mode)
{
    (void)path; (void)mode;
    return 0;
}

int fcntl(int fd, int cmd, ...)
{
    (void)fd; (void)cmd;
    return 0;
}

/* vm.js has no unlink(); emulate "delete" by truncating the file. */
int unlink(const char *path)
{
    int fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, 0666);

    if (fd < 0)
        return -1;
    close(fd);
    return 0;
}

int remove(const char *path)
{
    return unlink(path);
}

int access(const char *path, int mode)
{
    int fd;

    (void)mode;
    fd = open(path, O_RDONLY, 0);
    if (fd < 0)
        return -1;
    close(fd);
    return 0;
}

int stat(const char *path, struct stat *buf)
{
    int fd;
    long size;

    fd = open(path, O_RDONLY, 0);
    if (fd < 0)
        return -1;
    size = lseek(fd, 0, SEEK_END);
    close(fd);

    if (buf != NULL) {
        memset(buf, 0, sizeof(*buf));
        buf->st_mode = S_IFREG | 0644;
        buf->st_size = size < 0 ? 0 : size;
        buf->st_nlink = 1;
    }
    return 0;
}

int fstat(int fd, struct stat *buf)
{
    long cur, size;

    cur = lseek(fd, 0, SEEK_CUR);
    size = lseek(fd, 0, SEEK_END);
    lseek(fd, cur, SEEK_SET);

    if (buf != NULL) {
        memset(buf, 0, sizeof(*buf));
        buf->st_mode = S_IFREG | 0644;
        buf->st_size = size < 0 ? 0 : size;
        buf->st_nlink = 1;
    }
    return 0;
}

time_t time(time_t *t)
{
    /* Never hand the pointer to the VM: its SYS_time writes to addr>>2. */
    time_t v = (time_t)__syscall(SYS_time, 0, 0, 0);

    if (t != NULL)
        *t = v;
    return v;
}

