/* ctype                                                                */
/* ------------------------------------------------------------------ */

int isascii(int c)  { return (unsigned)c < 128u; }
int isdigit(int c)  { return c >= '0' && c <= '9'; }
int isxdigit(int c) { return isdigit(c) || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F'); }
int islower(int c)  { return c >= 'a' && c <= 'z'; }
int isupper(int c)  { return c >= 'A' && c <= 'Z'; }
int isalpha(int c)  { return islower(c) || isupper(c); }
int isalnum(int c)  { return isalpha(c) || isdigit(c); }
int isspace(int c)  { return c == ' ' || (c >= '\t' && c <= '\r'); }
int isblank(int c)  { return c == ' ' || c == '\t'; }
int isprint(int c)  { return c >= 0x20 && c < 0x7f; }
int isgraph(int c)  { return c > 0x20 && c < 0x7f; }
int iscntrl(int c)  { return (c >= 0 && c < 0x20) || c == 0x7f; }
int ispunct(int c)  { return isgraph(c) && !isalnum(c); }
int tolower(int c)  { return isupper(c) ? c + 32 : c; }
int toupper(int c)  { return islower(c) ? c - 32 : c; }

/* ------------------------------------------------------------------ */
/* heap: sbrk + K&R style malloc                                        */
/* ------------------------------------------------------------------ */

extern char __heap_start[];

static char *__brk;

void *sbrk(int incr)
{
    char *old;

    if (__brk == NULL)
        __brk = (char *)((((uintptr_t)__heap_start) + 7u) & ~(uintptr_t)7u);

    old = __brk;
    __brk += (incr + 7) & ~7;
    return old;
}

typedef struct __header {
    struct __header *next;
    size_t size;                /* in units of sizeof(struct __header) */
} Header;

static Header __base;
static Header *__freep;

#define NALLOC 4096u            /* minimum units requested from sbrk */

static Header *__morecore(size_t nu)
{
    char *cp;
    Header *up;

    if (nu < NALLOC)
        nu = NALLOC;

    cp = (char *)sbrk((int)(nu * sizeof(Header)));
    if (cp == (char *)-1)
        return NULL;

    up = (Header *)cp;
    up->size = nu;
    free((void *)(up + 1));
    return __freep;
}

void *malloc(size_t nbytes)
{
    Header *p, *prevp;
    size_t nunits;

    if (nbytes == 0)
        nbytes = 1;

    nunits = (nbytes + sizeof(Header) - 1) / sizeof(Header) + 1;

    prevp = __freep;
    if (prevp == NULL) {
        __base.next = &__base;
        __base.size = 0;
        __freep = &__base;
        prevp = &__base;
    }

    for (p = prevp->next;; prevp = p, p = p->next) {
        if (p->size >= nunits) {
            if (p->size == nunits) {
                prevp->next = p->next;
            } else {
                p->size -= nunits;
                p += p->size;
                p->size = nunits;
            }
            __freep = prevp;
            return (void *)(p + 1);
        }
        if (p == __freep) {
            p = __morecore(nunits);
            if (p == NULL)
                return NULL;
        }
    }
}

void free(void *ap)
{
    Header *bp, *p;

    if (ap == NULL)
        return;

    bp = (Header *)ap - 1;

    for (p = __freep; !(bp > p && bp < p->next); p = p->next) {
        if (p >= p->next && (bp > p || bp < p->next))
            break;              /* freed block at start or end of arena */
    }

    if (bp + bp->size == p->next) {
        bp->size += p->next->size;
        bp->next = p->next->next;
    } else {
        bp->next = p->next;
    }

    if (p + p->size == bp) {
        p->size += bp->size;
        p->next = bp->next;
    } else {
        p->next = bp;
    }

    __freep = p;
}

void *calloc(size_t n, size_t sz)
{
    size_t total = n * sz;
    void *p = malloc(total);

    if (p != NULL)
        memset(p, 0, total);
    return p;
}

void *realloc(void *p, size_t n)
{
    Header *h;
    size_t old;
    void *np;

    if (p == NULL)
        return malloc(n);
    if (n == 0) {
        free(p);
        return NULL;
    }

    h = (Header *)p - 1;
    old = (h->size - 1) * sizeof(Header);
    if (old >= n)
        return p;

    np = malloc(n);
    if (np == NULL)
        return NULL;
    memcpy(np, p, old);
    free(p);
    return np;
}

/* ------------------------------------------------------------------ */
/* numeric conversion                                                   */
/* ------------------------------------------------------------------ */

int abs(int v)   { return v < 0 ? -v : v; }
long labs(long v) { return v < 0 ? -v : v; }

long strtol(const char *s, char **end, int base)
{
    const char *p = s;
    int neg = 0;
    long v = 0;

    while (isspace((unsigned char)*p))
        p++;
    if (*p == '+' || *p == '-')
        neg = (*p++ == '-');

    if ((base == 0 || base == 16) && p[0] == '0' &&
        (p[1] == 'x' || p[1] == 'X')) {
        p += 2;
        base = 16;
    } else if (base == 0) {
        base = (p[0] == '0') ? 8 : 10;
    }

    for (;;) {
        int d;

        if (isdigit((unsigned char)*p))
            d = *p - '0';
        else if (isalpha((unsigned char)*p))
            d = tolower((unsigned char)*p) - 'a' + 10;
        else
            break;

        if (d >= base)
            break;
        v = v * base + d;
        p++;
    }

    if (end != NULL)
        *end = (char *)p;
    return neg ? -v : v;
}

unsigned long strtoul(const char *s, char **end, int base)
{
    return (unsigned long)strtol(s, end, base);
}

int atoi(const char *s)  { return (int)strtol(s, NULL, 10); }
long atol(const char *s) { return strtol(s, NULL, 10); }

double strtod(const char *s, char **end)
{
    const char *p = s;
    int neg = 0;
    double v = 0.0;

    while (isspace((unsigned char)*p))
        p++;
    if (*p == '+' || *p == '-')
        neg = (*p++ == '-');

    while (isdigit((unsigned char)*p))
        v = v * 10.0 + (double)(*p++ - '0');

    if (*p == '.') {
        double scale = 0.1;

        p++;
        while (isdigit((unsigned char)*p)) {
            v += scale * (double)(*p++ - '0');
            scale *= 0.1;
        }
    }

    if (*p == 'e' || *p == 'E') {
        const char *q = p + 1;
        int eneg = 0;
        int e = 0;

        if (*q == '+' || *q == '-')
            eneg = (*q++ == '-');
        if (isdigit((unsigned char)*q)) {
            while (isdigit((unsigned char)*q))
                e = e * 10 + (*q++ - '0');
            while (e-- > 0)
                v = eneg ? v / 10.0 : v * 10.0;
            p = q;
        }
    }

    if (end != NULL)
        *end = (char *)p;
    return neg ? -v : v;
}

double atof(const char *s)
{
    return strtod(s, NULL);
}

static unsigned int __rand_state = 1;

int rand(void)
{
    __rand_state = __rand_state * 1103515245u + 12345u;
    return (int)((__rand_state >> 16) & 0x7fff);
}

void srand(unsigned int seed)
{
    __rand_state = seed;
}

void qsort(void *base, size_t nmemb, size_t size,
           int (*cmp)(const void *, const void *))
{
    char *b = (char *)base;
    size_t i, j;

    /* insertion sort: small n only in doom */
    for (i = 1; i < nmemb; i++) {
        for (j = i; j > 0; j--) {
            char *x = b + (j - 1) * size;
            char *y = b + j * size;
            size_t k;

            if (cmp(x, y) <= 0)
                break;
            for (k = 0; k < size; k++) {
                char t = x[k];

                x[k] = y[k];
                y[k] = t;
            }
        }
    }
}

void *bsearch(const void *key, const void *base, size_t nmemb, size_t size,
              int (*cmp)(const void *, const void *))
{
    size_t lo = 0, hi = nmemb;

    while (lo < hi) {
        size_t mid = (lo + hi) / 2;
        const char *p = (const char *)base + mid * size;
        int r = cmp(key, p);

        if (r == 0)
            return (void *)p;
        if (r < 0)
            hi = mid;
        else
            lo = mid + 1;
    }
    return NULL;
}

/* ------------------------------------------------------------------ */
/* math (only what doom needs)                                          */
/* ------------------------------------------------------------------ */

double fabs(double x)  { return x < 0.0 ? -x : x; }
float fabsf(float x)   { return x < 0.0f ? -x : x; }

double floor(double x)
{
    double t = (double)(long long)x;

    if (t > x)
        t -= 1.0;
    return t;
}

double ceil(double x)
{
    double t = (double)(long long)x;

    if (t < x)
        t += 1.0;
    return t;
}

double round(double x)
{
    return x < 0.0 ? -floor(-x + 0.5) : floor(x + 0.5);
}

double fmod(double x, double y)
{
    double q;

    if (y == 0.0)
        return 0.0;
    q = x / y;
    q = q < 0.0 ? ceil(q) : floor(q);
    return x - q * y;
}

double sqrt(double x)
{
    double r;
    int i;

    if (x <= 0.0)
        return 0.0;

    r = x;
    for (i = 0; i < 64; i++) {
        double nr = 0.5 * (r + x / r);

        if (nr == r)
            break;
        r = nr;
    }
    return r;
}

float sqrtf(float x) { return (float)sqrt((double)x); }

double ldexp(double x, int e)
{
    while (e > 0) { x *= 2.0; e--; }
    while (e < 0) { x /= 2.0; e++; }
    return x;
}

double exp(double x)
{
    double term = 1.0, sum = 1.0;
    int n, k = 0;

    while (x > 1.0)  { x -= 1.0; k++; }
    while (x < -1.0) { x += 1.0; k--; }

    for (n = 1; n < 20; n++) {
        term *= x / (double)n;
        sum += term;
    }
    while (k > 0) { sum *= 2.718281828459045; k--; }
    while (k < 0) { sum /= 2.718281828459045; k++; }
    return sum;
}

double log(double x)
{
    double y, num, den;
    int e = 0;
    int n;

    if (x <= 0.0)
        return -1.0e300;

    while (x > 2.0)  { x /= 2.0; e++; }
    while (x < 0.5)  { x *= 2.0; e--; }

    /* atanh series around 1 */
    y = (x - 1.0) / (x + 1.0);
    num = y;
    den = 1.0;
    {
        double sum = 0.0;
        double y2 = y * y;

        for (n = 0; n < 30; n++) {
            sum += num / den;
            num *= y2;
            den += 2.0;
        }
        return 2.0 * sum + (double)e * 0.6931471805599453;
    }
}

double log10(double x) { return log(x) / 2.302585092994046; }

double pow(double x, double y)
{
    if (y == 0.0)
        return 1.0;
    if (x == 0.0)
        return 0.0;
    if (x < 0.0) {
        long long iy = (long long)y;

        if ((double)iy == y)
            return ((iy & 1) ? -1.0 : 1.0) * exp(y * log(-x));
        return 0.0;
    }
    return exp(y * log(x));
}

static double __sin_core(double x)
{
    double term, sum;
    int n;

    /* reduce to [-pi, pi] */
    while (x > 3.14159265358979323846)
        x -= 6.283185307179586;
    while (x < -3.14159265358979323846)
        x += 6.283185307179586;

    term = x;
    sum = x;
    for (n = 1; n < 12; n++) {
        term *= -x * x / (double)((2 * n) * (2 * n + 1));
        sum += term;
    }
    return sum;
}

double sin(double x) { return __sin_core(x); }
double cos(double x) { return __sin_core(x + 1.5707963267948966); }

double tan(double x)
{
    double c = cos(x);

    if (c == 0.0)
        return 1.0e300;
    return sin(x) / c;
}

double atan(double x)
{
    double sum = 0.0, term;
    int n;
    int inv = 0;
    int neg = 0;

    if (x < 0.0) {
        x = -x;
        neg = 1;
    }
    if (x > 1.0) {
        x = 1.0 / x;
        inv = 1;
    }

    term = x;
    for (n = 0; n < 60; n++) {
        sum += term / (double)(2 * n + 1) * ((n & 1) ? -1.0 : 1.0);
        term *= x * x;
    }
    if (inv)
        sum = 1.5707963267948966 - sum;
    return neg ? -sum : sum;
}

double atan2(double y, double x)
{
    if (x > 0.0)
        return atan(y / x);
    if (x < 0.0) {
        if (y >= 0.0)
            return atan(y / x) + 3.14159265358979323846;
        return atan(y / x) - 3.14159265358979323846;
    }
    if (y > 0.0)
        return 1.5707963267948966;
    if (y < 0.0)
        return -1.5707963267948966;
    return 0.0;
}

double asin(double x)
{
    if (x >= 1.0)
        return 1.5707963267948966;
    if (x <= -1.0)
        return -1.5707963267948966;
    return atan(x / sqrt(1.0 - x * x));
}

double acos(double x)
{
    return 1.5707963267948966 - asin(x);
}

/* ------------------------------------------------------------------ */
/* stdio                                                                */
/* ------------------------------------------------------------------ */

#define F_READ    0x01
#define F_WRITE   0x02
#define F_EOF     0x04
#define F_ERR     0x08
#define F_USED    0x10
#define F_LINEBUF 0x20
#define F_NOBUF   0x40

#define FBUFSZ 1024

struct _IO_FILE {
    int fd;
    int flags;
    int rpos;                   /* next byte in buf to be read */
    int rlen;                   /* valid bytes in buf */
    int wlen;                   /* bytes pending in buf */
    int ungot;                  /* pushed back char, or -1 */
    unsigned char buf[FBUFSZ];
};

#define NFILES 12

static FILE __files[NFILES];

static FILE __stdin  = { 0, F_READ | F_USED, 0, 0, 0, -1, { 0 } };
static FILE __stdout = { 1, F_WRITE | F_USED | F_LINEBUF, 0, 0, 0, -1, { 0 } };
static FILE __stderr = { 2, F_WRITE | F_USED | F_NOBUF, 0, 0, 0, -1, { 0 } };

FILE *stdin = &__stdin;
FILE *stdout = &__stdout;
FILE *stderr = &__stderr;

static int __flushbuf(FILE *f)
{
    int done = 0;

    while (done < f->wlen) {
        int n = (int)write(f->fd, f->buf + done, (size_t)(f->wlen - done));

        if (n <= 0) {
            f->flags |= F_ERR;
            f->wlen = 0;
            return EOF;
        }
        done += n;
    }
    f->wlen = 0;
    return 0;
}

int fflush(FILE *f)
{
    int i;

    if (f == NULL) {
        fflush(stdout);
        fflush(stderr);
        for (i = 0; i < NFILES; i++) {
            if (__files[i].flags & F_USED)
                fflush(&__files[i]);
        }
        return 0;
    }
    if ((f->flags & F_WRITE) && f->wlen > 0)
        return __flushbuf(f);
    return 0;
}

static int __putb(FILE *f, int c)
{
    if (f->flags & F_NOBUF) {
        unsigned char ch = (unsigned char)c;

        if (write(f->fd, &ch, 1) != 1) {
            f->flags |= F_ERR;
            return EOF;
        }
        return (unsigned char)c;
    }

    f->buf[f->wlen++] = (unsigned char)c;
    if (f->wlen >= FBUFSZ ||
        ((f->flags & F_LINEBUF) && c == '\n')) {
        if (__flushbuf(f) != 0)
            return EOF;
    }
    return (unsigned char)c;
}

static size_t __writeb(FILE *f, const unsigned char *p, size_t n)
{
    size_t done = 0;

    if (n >= FBUFSZ / 2) {
        /* bulk: flush the buffer and write straight through */
        if (f->wlen > 0 && __flushbuf(f) != 0)
            return 0;
        while (done < n) {
            int w = (int)write(f->fd, p + done, n - done);

            if (w <= 0) {
                f->flags |= F_ERR;
                break;
            }
            done += (size_t)w;
        }
        return done;
    }

    while (done < n) {
        if (__putb(f, p[done]) == EOF)
            break;
        done++;
    }
    return done;
}

static int __fillb(FILE *f)
{
    int n;

    if (f->flags & F_EOF)
        return EOF;

    n = (int)read(f->fd, f->buf, FBUFSZ);
    if (n <= 0) {
        f->flags |= (n == 0) ? F_EOF : F_ERR;
        f->rpos = 0;
        f->rlen = 0;
        return EOF;
    }
    f->rpos = 0;
    f->rlen = n;
    return 0;
}

static FILE *__alloc_file(void)
{
    int i;

    for (i = 0; i < NFILES; i++) {
        if (!(__files[i].flags & F_USED)) {
            memset(&__files[i], 0, sizeof(FILE));
            __files[i].ungot = -1;
            __files[i].flags = F_USED;
            return &__files[i];
        }
    }
    return NULL;
}

FILE *fopen(const char *path, const char *mode)
{
    FILE *f;
    int flags = 0;
    int oflags;
    int fd;
    int plus = (strchr(mode, '+') != NULL);

    switch (mode[0]) {
    case 'r':
        oflags = plus ? O_RDWR : O_RDONLY;
        flags = plus ? (F_READ | F_WRITE) : F_READ;
        break;
    case 'w':
        oflags = O_WRONLY | O_CREAT | O_TRUNC;
        flags = F_WRITE;
        break;
    case 'a':
        oflags = O_WRONLY | O_CREAT | O_APPEND;
        flags = F_WRITE;
        break;
    default:
        return NULL;
    }

    fd = open(path, oflags, 0666);
    if (fd < 0)
        return NULL;

    f = __alloc_file();
    if (f == NULL) {
        close(fd);
        return NULL;
    }

    f->fd = fd;
    f->flags |= flags;
    return f;
}

FILE *fdopen(int fd, const char *mode)
{
    FILE *f = __alloc_file();

    if (f == NULL)
        return NULL;
    f->fd = fd;
    f->flags |= (mode[0] == 'r') ? F_READ : F_WRITE;
    return f;
}

FILE *freopen(const char *path, const char *mode, FILE *f)
{
    if (f != NULL)
        fclose(f);
    return fopen(path, mode);
}

int fclose(FILE *f)
{
    int r = 0;

    if (f == NULL)
        return EOF;

    fflush(f);
    if (f->fd > 2)
        r = close(f->fd);

    if (f != stdin && f != stdout && f != stderr)
        f->flags = 0;
    return r;
}

int fileno(FILE *f) { return f->fd; }

int setvbuf(FILE *f, char *buf, int mode, size_t size)
{
    (void)buf;
    (void)size;
    fflush(f);
    f->flags &= ~(F_LINEBUF | F_NOBUF);
    if (mode == _IONBF)
        f->flags |= F_NOBUF;
    else if (mode == _IOLBF)
        f->flags |= F_LINEBUF;
    return 0;
}

void setbuf(FILE *f, char *buf)
{
    setvbuf(f, buf, buf != NULL ? _IOFBF : _IONBF, FBUFSZ);
}

int fputc(int c, FILE *f)
{
    return __putb(f, c);
}

int putc(int c, FILE *f) { return fputc(c, f); }
int putchar(int c)       { return fputc(c, stdout); }

int fputs(const char *s, FILE *f)
{
    size_t n = strlen(s);

    return (__writeb(f, (const unsigned char *)s, n) == n) ? 0 : EOF;
}

int puts(const char *s)
{
    if (fputs(s, stdout) == EOF)
        return EOF;
    return fputc('\n', stdout);
}

int fgetc(FILE *f)
{
    if (f->ungot >= 0) {
        int c = f->ungot;

        f->ungot = -1;
        return c;
    }
    if (f->rpos >= f->rlen) {
        if (__fillb(f) != 0)
            return EOF;
    }
    return f->buf[f->rpos++];
}

int getc(FILE *f)   { return fgetc(f); }
int getchar(void)   { return fgetc(stdin); }

int ungetc(int c, FILE *f)
{
    if (c == EOF)
        return EOF;
    f->ungot = (unsigned char)c;
    f->flags &= ~F_EOF;
    return (unsigned char)c;
}

char *fgets(char *s, int n, FILE *f)
{
    int i = 0;
    int c = 0;

    if (n <= 0)
        return NULL;

    while (i < n - 1) {
        c = fgetc(f);
        if (c == EOF)
            break;
        s[i++] = (char)c;
        if (c == '\n')
            break;
    }
    if (i == 0 && c == EOF)
        return NULL;
    s[i] = '\0';
    return s;
}

size_t fread(void *ptr, size_t size, size_t nmemb, FILE *f)
{
    unsigned char *p = (unsigned char *)ptr;
    size_t total = size * nmemb;
    size_t done = 0;

    if (total == 0)
        return 0;

    if (f->ungot >= 0) {
        p[done++] = (unsigned char)f->ungot;
        f->ungot = -1;
    }

    /* drain the buffer first */
    while (done < total && f->rpos < f->rlen)
        p[done++] = f->buf[f->rpos++];

    /* bulk read the rest directly */
    while (done < total) {
        size_t want = total - done;
        int n;

        if (want < FBUFSZ) {
            if (__fillb(f) != 0)
                break;
            while (done < total && f->rpos < f->rlen)
                p[done++] = f->buf[f->rpos++];
            continue;
        }

        n = (int)read(f->fd, p + done, want);
        if (n <= 0) {
            f->flags |= (n == 0) ? F_EOF : F_ERR;
            break;
        }
        done += (size_t)n;
    }

    return size ? done / size : 0;
}

size_t fwrite(const void *ptr, size_t size, size_t nmemb, FILE *f)
{
    size_t total = size * nmemb;
    size_t done;

    if (total == 0)
        return 0;
    done = __writeb(f, (const unsigned char *)ptr, total);
    return size ? done / size : 0;
}

int fseek(FILE *f, long off, int whence)
{
    long base;

    if (f->flags & F_WRITE)
        fflush(f);

    if (whence == SEEK_CUR) {
        /* account for buffered-but-unconsumed input */
        base = lseek(f->fd, 0, SEEK_CUR);
        if (base < 0)
            return -1;
        off += base - (long)(f->rlen - f->rpos) - (f->ungot >= 0 ? 1 : 0);
        whence = SEEK_SET;
    }

    f->rpos = 0;
    f->rlen = 0;
    f->ungot = -1;
    f->flags &= ~F_EOF;

    if (lseek(f->fd, off, whence) < 0)
        return -1;
    return 0;
}

long ftell(FILE *f)
{
    long pos;

    if (f->flags & F_WRITE)
        fflush(f);

    pos = lseek(f->fd, 0, SEEK_CUR);
    if (pos < 0)
        return -1;
    pos -= (long)(f->rlen - f->rpos);
    if (f->ungot >= 0)
        pos--;
    return pos;
}

void rewind(FILE *f)
{
    fseek(f, 0, SEEK_SET);
    f->flags &= ~(F_EOF | F_ERR);
}

int feof(FILE *f)   { return (f->flags & F_EOF) != 0; }
int ferror(FILE *f) { return (f->flags & F_ERR) != 0; }
void clearerr(FILE *f) { f->flags &= ~(F_EOF | F_ERR); }

void perror(const char *s)
{
    if (s != NULL && *s != '\0')
        fprintf(stderr, "%s: ", s);
    fprintf(stderr, "%s\n", strerror(errno));
}

/* ------------------------------------------------------------------ */
/* formatted output                                                     */
/* ------------------------------------------------------------------ */

typedef struct {
    FILE *f;                    /* target stream, or NULL for a buffer */
    char *buf;
    size_t size;                /* buffer capacity (including NUL) */
    size_t len;                 /* characters emitted (may exceed size) */
} __outctx;

static void __out(__outctx *o, const char *s, size_t n)
{
    if (o->f != NULL) {
        __writeb(o->f, (const unsigned char *)s, n);
        o->len += n;
        return;
    }

    if (o->buf != NULL && o->size > 0) {
        size_t space = (o->len < o->size - 1) ? (o->size - 1 - o->len) : 0;
        size_t cnt = n < space ? n : space;

        if (cnt > 0)
            memcpy(o->buf + o->len, s, cnt);
    }
    o->len += n;
}

static void __outc(__outctx *o, char c)
{
    __out(o, &c, 1);
}

static void __pad(__outctx *o, char c, int n)
{
    while (n-- > 0)
        __outc(o, c);
}

static int __utoa(char *dst, unsigned long long v, unsigned base, int upper)
{
    static const char *ld = "0123456789abcdef";
    static const char *ud = "0123456789ABCDEF";
    const char *digits = upper ? ud : ld;
    char tmp[24];
    int n = 0;
    int i;

    if (v == 0)
        tmp[n++] = '0';
    while (v != 0) {
        tmp[n++] = digits[v % base];
        v /= base;
    }
    for (i = 0; i < n; i++)
        dst[i] = tmp[n - 1 - i];
    dst[n] = '\0';
    return n;
}

static void __fmt_double(__outctx *o, double v, int prec, int width,
                         int leftalign, int zeropad, int plus)
{
    char intbuf[32];
    char out[96];
    int n = 0;
    int neg = 0;
    unsigned long long ip;
    double frac;
    int i, len;

    if (prec < 0)
        prec = 6;
    if (prec > 17)
        prec = 17;

    if (v < 0.0) {
        neg = 1;
        v = -v;
    }

    /* round at the requested precision */
    {
        double r = 0.5;

        for (i = 0; i < prec; i++)
            r /= 10.0;
        v += r;
    }

    if (v >= 1.8e19) {
        const char *s = neg ? "-inf" : "inf";

        __out(o, s, strlen(s));
        return;
    }

    ip = (unsigned long long)v;
    frac = v - (double)ip;

    if (neg)
        out[n++] = '-';
    else if (plus)
        out[n++] = '+';

    len = __utoa(intbuf, ip, 10, 0);
    for (i = 0; i < len; i++)
        out[n++] = intbuf[i];

    if (prec > 0) {
        out[n++] = '.';
        for (i = 0; i < prec; i++) {
            int d;

            frac *= 10.0;
            d = (int)frac;
            if (d < 0)
                d = 0;
            if (d > 9)
                d = 9;
            out[n++] = (char)('0' + d);
            frac -= (double)d;
        }
    }

    if (width > n && !leftalign) {
        if (zeropad) {
            int start = (out[0] == '-' || out[0] == '+') ? 1 : 0;

            if (start)
                __outc(o, out[0]);
            __pad(o, '0', width - n);
            __out(o, out + start, (size_t)(n - start));
            return;
        }
        __pad(o, ' ', width - n);
    }

    __out(o, out, (size_t)n);

    if (width > n && leftalign)
        __pad(o, ' ', width - n);
}

static int __vformat(__outctx *o, const char *fmt, va_list ap)
{
    const char *p = fmt;

    while (*p != '\0') {
        int leftalign = 0, plus = 0, space = 0, zeropad = 0, alt = 0;
        int width = 0, prec = -1;
        int lmod = 0;           /* 0=int 1=long 2=long long 3=short 4=char */
        char conv;
        char numbuf[32];
        const char *sval;
        char cval;
        int len;
        int negnum = 0;
        const char *prefix = "";

        if (*p != '%') {
            const char *start = p;

            while (*p != '\0' && *p != '%')
                p++;
            __out(o, start, (size_t)(p - start));
            continue;
        }
        p++;

        for (;;) {
            if (*p == '-')      leftalign = 1;
            else if (*p == '+') plus = 1;
            else if (*p == ' ') space = 1;
            else if (*p == '0') zeropad = 1;
            else if (*p == '#') alt = 1;
            else break;
            p++;
        }

        if (*p == '*') {
            width = va_arg(ap, int);
            if (width < 0) {
                leftalign = 1;
                width = -width;
            }
            p++;
        } else {
            while (isdigit((unsigned char)*p))
                width = width * 10 + (*p++ - '0');
        }

        if (*p == '.') {
            p++;
            prec = 0;
            if (*p == '*') {
                prec = va_arg(ap, int);
                p++;
            } else {
                while (isdigit((unsigned char)*p))
                    prec = prec * 10 + (*p++ - '0');
            }
            if (prec < 0)
                prec = -1;
        }

        for (;;) {
            if (*p == 'l') {
                lmod = (lmod == 1) ? 2 : 1;
                p++;
            } else if (*p == 'h') {
                lmod = (lmod == 3) ? 4 : 3;
                p++;
            } else if (*p == 'z' || *p == 'j' || *p == 't') {
                lmod = 1;
                p++;
            } else if (*p == 'L') {
                p++;
            } else {
                break;
            }
        }

        conv = *p;
        if (conv == '\0')
            break;
        p++;

        switch (conv) {
        case '%':
            __outc(o, '%');
            continue;

        case 'c':
            cval = (char)va_arg(ap, int);
            if (!leftalign)
                __pad(o, ' ', width - 1);
            __outc(o, cval);
            if (leftalign)
                __pad(o, ' ', width - 1);
            continue;

        case 's':
            sval = va_arg(ap, const char *);
            if (sval == NULL)
                sval = "(null)";
            len = (int)((prec >= 0) ? strnlen(sval, (size_t)prec) : strlen(sval));
            if (!leftalign)
                __pad(o, ' ', width - len);
            __out(o, sval, (size_t)len);
            if (leftalign)
                __pad(o, ' ', width - len);
            continue;

        case 'd':
        case 'i': {
            long long v;
            unsigned long long uv;

            if (lmod == 2)      v = va_arg(ap, long long);
            else if (lmod == 1) v = va_arg(ap, long);
            else if (lmod == 3) v = (short)va_arg(ap, int);
            else if (lmod == 4) v = (signed char)va_arg(ap, int);
            else                v = va_arg(ap, int);

            if (v < 0) {
                negnum = 1;
                uv = (unsigned long long)(-v);
            } else {
                uv = (unsigned long long)v;
            }
            len = __utoa(numbuf, uv, 10, 0);
            if (negnum)
                prefix = "-";
            else if (plus)
                prefix = "+";
            else if (space)
                prefix = " ";
            break;
        }

        case 'u':
        case 'o':
        case 'x':
        case 'X':
        case 'p': {
            unsigned long long uv;
            unsigned base = 10;
            int upper = 0;

            if (conv == 'p') {
                uv = (unsigned long long)(uintptr_t)va_arg(ap, void *);
                base = 16;
                prefix = "0x";
            } else {
                if (lmod == 2)      uv = va_arg(ap, unsigned long long);
                else if (lmod == 1) uv = va_arg(ap, unsigned long);
                else if (lmod == 3) uv = (unsigned short)va_arg(ap, unsigned int);
                else if (lmod == 4) uv = (unsigned char)va_arg(ap, unsigned int);
                else                uv = va_arg(ap, unsigned int);

                if (conv == 'o')
                    base = 8;
                else if (conv == 'x' || conv == 'X')
                    base = 16;
                if (conv == 'X')
                    upper = 1;
                if (alt && uv != 0 && base == 16)
                    prefix = upper ? "0X" : "0x";
                if (alt && base == 8)
                    prefix = "0";
            }
            len = __utoa(numbuf, uv, base, upper);
            break;
        }

        case 'f':
        case 'F':
        case 'e':
        case 'E':
        case 'g':
        case 'G':
            __fmt_double(o, va_arg(ap, double), prec, width, leftalign,
                         zeropad, plus);
            continue;

        case 'n': {
            int *ip = va_arg(ap, int *);

            if (ip != NULL)
                *ip = (int)o->len;
            continue;
        }

        default:
            __outc(o, '%');
            __outc(o, conv);
            continue;
        }

        /* integer output shared tail */
        {
            int plen = (int)strlen(prefix);
            int zeros = 0;
            int total;

            if (prec >= 0 && len < prec)
                zeros = prec - len;
            else if (zeropad && !leftalign && width > plen + len)
                zeros = width - plen - len;

            total = plen + zeros + len;

            if (!leftalign)
                __pad(o, ' ', width - total);
            __out(o, prefix, (size_t)plen);
            __pad(o, '0', zeros);
            __out(o, numbuf, (size_t)len);
            if (leftalign)
                __pad(o, ' ', width - total);
        }
    }

    return (int)o->len;
}

int vfprintf(FILE *f, const char *fmt, va_list ap)
{
    __outctx o;

    o.f = f;
    o.buf = NULL;
    o.size = 0;
    o.len = 0;
    return __vformat(&o, fmt, ap);
}

int vprintf(const char *fmt, va_list ap)
{
    return vfprintf(stdout, fmt, ap);
}

int vsnprintf(char *buf, size_t n, const char *fmt, va_list ap)
{
    __outctx o;
    int r;

    o.f = NULL;
    o.buf = buf;
    o.size = n;
    o.len = 0;
    r = __vformat(&o, fmt, ap);
    if (buf != NULL && n > 0)
        buf[(o.len < n - 1) ? o.len : n - 1] = '\0';
    return r;
}

int vsprintf(char *buf, const char *fmt, va_list ap)
{
    return vsnprintf(buf, (size_t)0x7fffffff, fmt, ap);
}

int printf(const char *fmt, ...)
{
    va_list ap;
    int r;

    va_start(ap, fmt);
    r = vfprintf(stdout, fmt, ap);
    va_end(ap);
    return r;
}

int fprintf(FILE *f, const char *fmt, ...)
{
    va_list ap;
    int r;

    va_start(ap, fmt);
    r = vfprintf(f, fmt, ap);
    va_end(ap);
    return r;
}

int sprintf(char *buf, const char *fmt, ...)
{
    va_list ap;
    int r;

    va_start(ap, fmt);
    r = vsprintf(buf, fmt, ap);
    va_end(ap);
    return r;
}

int snprintf(char *buf, size_t n, const char *fmt, ...)
{
    va_list ap;
    int r;

    va_start(ap, fmt);
    r = vsnprintf(buf, n, fmt, ap);
    va_end(ap);
    return r;
}

/* ------------------------------------------------------------------ */
/* formatted input (subset used by doom)                                */
/* ------------------------------------------------------------------ */

int vsscanf(const char *str, const char *fmt, va_list ap)
{
    const char *s = str;
    const char *p = fmt;
    int assigned = 0;

    while (*p != '\0') {
        if (isspace((unsigned char)*p)) {
            while (isspace((unsigned char)*s))
                s++;
            p++;
            continue;
        }

        if (*p != '%') {
            if (*s != *p)
                return assigned;
            s++;
            p++;
            continue;
        }

        p++;
        {
            int suppress = 0;
            int width = 0;
            int lmod = 0;
            char conv;

            if (*p == '*') {
                suppress = 1;
                p++;
            }
            while (isdigit((unsigned char)*p))
                width = width * 10 + (*p++ - '0');
            while (*p == 'l' || *p == 'h' || *p == 'z') {
                if (*p == 'l')
                    lmod = 1;
                p++;
            }

            conv = *p;
            if (conv == '\0')
                break;
            p++;

            if (conv != 'c' && conv != '[') {
                while (isspace((unsigned char)*s))
                    s++;
            }

            switch (conv) {
            case 'd':
            case 'i':
            case 'u':
            case 'x':
            case 'X':
            case 'o': {
                char tmp[64];
                int i = 0;
                int base = (conv == 'x' || conv == 'X') ? 16 :
                           (conv == 'o') ? 8 :
                           (conv == 'i') ? 0 : 10;
                char *endp;
                long v;
                int maxw = (width > 0 && width < 63) ? width : 63;

                if (*s == '+' || *s == '-')
                    tmp[i++] = *s++;
                if ((base == 16 || base == 0) && s[0] == '0' &&
                    (s[1] == 'x' || s[1] == 'X') && i + 2 <= maxw) {
                    tmp[i++] = *s++;
                    tmp[i++] = *s++;
                }
                while (i < maxw && *s != '\0' &&
                       (isdigit((unsigned char)*s) ||
                        (base == 16 && isxdigit((unsigned char)*s))))
                    tmp[i++] = *s++;
                tmp[i] = '\0';
                if (i == 0)
                    return assigned;

                v = strtol(tmp, &endp, base);
                if (!suppress) {
                    if (lmod)
                        *va_arg(ap, long *) = v;
                    else
                        *va_arg(ap, int *) = (int)v;
                    assigned++;
                }
                break;
            }

            case 'f':
            case 'e':
            case 'g': {
                char *endp;
                double v = strtod(s, &endp);

                if (endp == s)
                    return assigned;
                s = endp;
                if (!suppress) {
                    if (lmod)
                        *va_arg(ap, double *) = v;
                    else
                        *va_arg(ap, float *) = (float)v;
                    assigned++;
                }
                break;
            }

            case 's': {
                char *dst = suppress ? NULL : va_arg(ap, char *);
                int i = 0;

                if (*s == '\0')
                    return assigned;
                while (*s != '\0' && !isspace((unsigned char)*s) &&
                       (width == 0 || i < width)) {
                    if (dst != NULL)
                        dst[i] = *s;
                    i++;
                    s++;
                }
                if (dst != NULL)
                    dst[i] = '\0';
                if (i == 0)
                    return assigned;
                if (!suppress)
                    assigned++;
                break;
            }

            case 'c': {
                char *dst = suppress ? NULL : va_arg(ap, char *);
                int cnt = width > 0 ? width : 1;
                int i;

                for (i = 0; i < cnt; i++) {
                    if (*s == '\0')
                        return assigned;
                    if (dst != NULL)
                        dst[i] = *s;
                    s++;
                }
                if (!suppress)
                    assigned++;
                break;
            }

            case '[': {
                int negate = 0;
                char set[256];
                char *dst;
                int i = 0;

                memset(set, 0, sizeof(set));
                if (*p == '^') {
                    negate = 1;
                    p++;
                }
                if (*p == ']') {
                    set[(unsigned char)']'] = 1;
                    p++;
                }
                while (*p != '\0' && *p != ']') {
                    if (p[1] == '-' && p[2] != '\0' && p[2] != ']') {
                        unsigned char c1 = (unsigned char)p[0];
                        unsigned char c2 = (unsigned char)p[2];

                        while (c1 <= c2)
                            set[c1++] = 1;
                        p += 3;
                    } else {
                        set[(unsigned char)*p] = 1;
                        p++;
                    }
                }
                if (*p == ']')
                    p++;

                dst = suppress ? NULL : va_arg(ap, char *);
                while (*s != '\0' && (width == 0 || i < width)) {
                    int in = set[(unsigned char)*s] != 0;

                    if (negate)
                        in = !in;
                    if (!in)
                        break;
                    if (dst != NULL)
                        dst[i] = *s;
                    i++;
                    s++;
                }
                if (dst != NULL)
                    dst[i] = '\0';
                if (i == 0)
                    return assigned;
                if (!suppress)
                    assigned++;
                break;
            }

            case '%':
                if (*s != '%')
                    return assigned;
                s++;
                break;

            default:
                return assigned;
            }
        }
    }

    return assigned;
}

int sscanf(const char *str, const char *fmt, ...)
{
    va_list ap;
    int r;

    va_start(ap, fmt);
    r = vsscanf(str, fmt, ap);
    va_end(ap);
    return r;
}

/*
 * fscanf: read one line and run it through vsscanf.  Doom only uses it to
 * parse "key value" lines out of the config file.
 */
int fscanf(FILE *f, const char *fmt, ...)
{
    char line[512];
    va_list ap;
    int r;

    if (fgets(line, (int)sizeof(line), f) == NULL)
        return EOF;

    va_start(ap, fmt);
    r = vsscanf(line, fmt, ap);
    va_end(ap);
    return r;
}

/* ------------------------------------------------------------------ */
/* process control                                                      */
/* ------------------------------------------------------------------ */

#define NATEXIT 32
static void (*__atexit_fns[NATEXIT])(void);
static int __natexit;

int atexit(void (*fn)(void))
{
    if (__natexit >= NATEXIT)
        return -1;
    __atexit_fns[__natexit++] = fn;
    return 0;
}

static void __halt(void)
{
    /*
     * A branch to itself: vm.js stops the machine as soon as the pc stops
     * moving, which is the cleanest way to terminate.
     */
    for (;;) {
        asm volatile (".set noreorder\n"
                      "1: b 1b\n"
                      "   nop\n"
                      ".set reorder\n");
    }
}

void _exit(int code)
{
    (void)code;
    __halt();
}

void exit(int code)
{
    while (__natexit > 0)
        __atexit_fns[--__natexit]();

    fflush(NULL);
    (void)code;
    __halt();
}

void abort(void)
{
    fflush(NULL);
    __halt();
}

void __assert_fail(const char *expr, const char *file, int line)
{
    fprintf(stderr, "Assertion failed: %s (%s:%d)\n", expr, file, line);
    abort();
}

/* ------------------------------------------------------------------ */
/* entry point                                                          */
/* ------------------------------------------------------------------ */

/*
 * vm.js starts execution at the symbol called "main", with $sp = 0x7ffffffc
 * and no valid $ra.  Set up an aligned stack and hand over to doom's main
 * (renamed to doom_main at compile time).
 */
extern int doom_main(int argc, char **argv);

void __libc_start(void)
{
    static char *argv[2] = { "doomgeneric", NULL };

    doom_main(1, argv);
    exit(0);
}

asm (
"    .set noreorder\n"
"    .globl main\n"
"    .type  main, @function\n"
"    .ent   main\n"
"main:\n"
"    lui  $sp, 0x7fff\n"
"    ori  $sp, $sp, 0xf000\n"
"    move $fp, $zero\n"
"    move $ra, $zero\n"
"    jal  __libc_start\n"
"    nop\n"
"1:  b    1b\n"
"    nop\n"
"    .end   main\n"
"    .set reorder\n"
);

/* Linker script for the vm.js MIPS machine.
 *
 * vm.js only loads the sections literally named .text, .rodata and .data,
 * starts at the symbol "main", and leaves everything else reading as zero,
 * which is exactly what .bss needs.
 */

ENTRY(main)

SECTIONS
{
    . = 0x00400000;

    .text : ALIGN(4)
    {
        *(.text.startup)
        *(.text.unlikely)
        *(.text)
        *(.text.*)
        *(.gnu.linkonce.t.*)
        . = ALIGN(4);
    }

    .rodata : ALIGN(4)
    {
        *(.rodata)
        *(.rodata.*)
        *(.rodata1)
        *(.lit4)
        *(.lit8)
        *(.gnu.linkonce.r.*)
        . = ALIGN(4);
    }

    .data : ALIGN(4)
    {
        *(.data)
        *(.data.*)
        *(.data1)
        *(.sdata)
        *(.sdata.*)
        *(.got)
        *(.gnu.linkonce.d.*)
        . = ALIGN(4);
    }

    .bss (NOLOAD) : ALIGN(8)
    {
        *(.bss)
        *(.bss.*)
        *(.sbss)
        *(.sbss.*)
        *(.scommon)
        *(COMMON)
        . = ALIGN(16);
    }

    __heap_start = ALIGN(., 16);
    _end = __heap_start;

    /DISCARD/ :
    {
        *(.eh_frame)
        *(.eh_frame_hdr)
        *(.comment)
        *(.note)
        *(.note.*)
        *(.reginfo)
        *(.MIPS.abiflags)
        *(.gnu.attributes)
        *(.pdr)
        *(.mdebug*)
    }
}

//
// my_stdlib.h - the freestanding runtime used by the MIPS/vm.js build.
//
// doomgeneric_img.c includes this instead of the hosted C headers; it just
// pulls in the headers of the minimal libc that is linked into the image.
//

#ifndef MY_STDLIB_H
#define MY_STDLIB_H

#include <stddef.h>
#include <stdint.h>
#include <stdarg.h>
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <ctype.h>
#include <unistd.h>

#endif

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct { int a; short b; int c; char n[8]; } __attribute__((packed)) pk_t;

static unsigned char raw[64];

int doom_main(int argc, char **argv)
{
    pk_t *p;
    int i;
    volatile signed char *sc;
    volatile int neg;
    FILE *f;
    char buf[32];
    int x, y;

    printf("hello from mips, argc=%d argv0=%s\n", argc, argv[0]);
    printf("num tests: %d %u %x %05d %-6d| %s %c %.2f\n",
           -12345, 4000000000u, 0xdeadbeef, 42, 7, "str", 'Z', 3.14159);

    for (i = 0; i < 64; i++)
        raw[i] = (unsigned char)(i * 7 + 1);

    p = (pk_t *)raw;            /* aligned base, packed struct */
    printf("packed a=%08x b=%04x c=%08x\n", p->a, (unsigned short)p->b, p->c);
    printf("expect  a=%08x b=%04x c=%08x\n", 0x160f0801u, 0x241du, 0x3a332c25u);

    p = (pk_t *)(raw + 1);      /* misaligned base */
    printf("packed2 a=%08x c=%08x\n", p->a, p->c);
    printf("expect2 a=%08x c=%08x\n", 0x1d160f08u, 0x413a332cu);

    /* unaligned store */
    p->a = 0x80abcdef;
    printf("store   a=%08x  raw=%02x %02x %02x %02x %02x\n", p->a,
           raw[0], raw[1], raw[2], raw[3], raw[4]);
    printf("expects a=80abcdef raw=01 ef cd ab 80\n");

    /* negative equality comparisons */
    sc = (volatile signed char *)raw;
    raw[10] = 0xff;
    sc = (volatile signed char *)&raw[10];
    neg = *sc;
    if (neg == -1)
        printf("neg compare ok\n");
    else
        printf("neg compare BROKEN (%d)\n", neg);

    /* 64-bit and division */
    {
        long long ll = 0x123456789abcdefLL;
        printf("64bit: %lld %lld %d %d\n", ll / 1000, ll %% 7, -17 / 3, -17 %% 3);
    }

    /* file io */
    f = fopen("/tmp/vmtest.txt", "wb");
    if (f == NULL) {
        printf("fopen write failed\n");
    } else {
        fprintf(f, "12 34 line\n");
        fclose(f);
        f = fopen("/tmp/vmtest.txt", "rb");
        if (f == NULL) {
            printf("fopen read failed\n");
        } else {
            if (fgets(buf, sizeof(buf), f) != NULL)
                printf("read back: %s", buf);
            fclose(f);
        }
    }

    if (sscanf("12 34", "%d %d", &x, &y) == 2)
        printf("sscanf ok %d %d\n", x, y);
    else
        printf("sscanf broken\n");

    {
        void *m1 = malloc(1000);
        void *m2 = malloc(100000);
        memset(m2, 0xab, 100000);
        free(m1);
        free(m2);
        printf("malloc ok %p %p\n", m1, m2);
    }

    printf("done\n");
    return 0;
}
